head.script:
tailwind.config = {
  darkMode: 'class',
  theme: {
    extend: {
      colors: {
        tnhub: {
          50: '#f0fdfa',
          100: '#ccfbf1',
          500: '#14b8a6',
          600: '#0d9488',
          700: '#0f766e',
          800: '#115e59',
          900: '#134e4a'
        }
      }
    }
  }
}

head.b:skin:
body {
  margin: 0;
  padding: 0;
  background-color: #f4f5f7;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}
.custom-scroll::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
.custom-scroll::-webkit-scrollbar-track {
  background: transparent;
}
.custom-scroll::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 9999px;
}

div.v-bind:class:
{
             "bg-emerald-50 border-emerald-500 text-emerald-900": toast.type === "success",
             "bg-rose-50 border-rose-500 text-rose-900": toast.type === "error",
             "bg-amber-50 border-amber-500 text-amber-900": toast.type === "warning",
             "bg-blue-50 border-blue-500 text-blue-900": toast.type === "info"
           }

{
               "bg-emerald-100 text-emerald-600": popup.type === "success",
               "bg-rose-100 text-rose-600": popup.type === "error",
               "bg-amber-100 text-amber-600": popup.type === "warning",
               "bg-blue-100 text-blue-600": popup.type === "info"
             }

button.v-bind:class:
{
                    "bg-slate-900 hover:bg-slate-800 text-white": popup.type === "success" || popup.type === "info",
                    "bg-rose-600 hover:bg-rose-700 text-white": popup.type === "error",
                    "bg-amber-600 hover:bg-amber-700 text-white": popup.type === "warning"
                  }

body.script:
//
import { initializeApp } from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-app.js';
import { 
  getAuth, 
  GoogleAuthProvider, 
  signInWithPopup, 
  signOut, 
  onAuthStateChanged 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-auth.js';
import { 
  getFirestore, 
  collection, 
  addDoc, 
  query, 
  orderBy, 
  limit, 
  onSnapshot, 
  doc, 
  setDoc, 
  serverTimestamp 
} from 'https://www.gstatic.com/firebasejs/10.9.0/firebase-firestore.js';

// CẤU HÌNH FIREBASE: TNHub-FireBase
const savedApiKey = localStorage.getItem('tnhub_firebase_api_key');
const firebaseConfig = {
  apiKey: savedApiKey || "AIzaSyB36E4W7BG8ZLQnfBLeZu-pVtf4TVDqLUQ",
  authDomain: "fir-1b417.firebaseapp.com",
  projectId: "fir-1b417",
  storageBucket: "fir-1b417.firebasestorage.app",
  messagingSenderId: "593916869236",
  appId: "1:593916869236:web:e7c6233011227b80f72f21",
  measurementId: "G-9604F39B4E"
};

// Google Apps Script Web App: TNHub-Script
const GAS_WEB_APP_URL = "https://script.google.com/macros/s/AKfycbzDummyTNHubScriptDeploymentId/exec";

// Initialize Firebase
let app, auth, db;
try {
  app = initializeApp(firebaseConfig);
  auth = getAuth(app);
  db = getFirestore(app);
} catch (e) {
  console.warn('Firebase init notice:', e.message);
}

const { createApp, ref, computed, onMounted } = Vue;

createApp({
  setup() {
    const activeTab = ref('feed');
    const activeCategory = ref('all');
    const viewMode = ref('grid');
    const searchKeyword = ref('');
    const userMenuOpen = ref(false);
    const showApplyModal = ref(false);
    const showContactModal = ref(false);
    const showPostModal = ref(false);
    const showConfigModal = ref(false);
    const submittingApply = ref(false);
    const selectedItem = ref(null);
    const customApiKey = ref(localStorage.getItem('tnhub_firebase_api_key') || '');

    const currentUser = ref({
      displayName: 'Phạm Thanh Quang',
      email: 'ptquang0968@gmail.com',
      photoURL: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=120&h=120&q=80'
    });

    const bookmarks = ref(JSON.parse(localStorage.getItem('tnhub_bookmarks') || '["c1"]'));

    const toasts = ref([]);
    const popup = ref({
      show: false,
      title: '',
      message: '',
      type: 'info',
      confirmText: 'Đã hiểu',
      showCancel: false,
      cancelText: 'Hủy',
      onConfirm: null
    });

    const showToast = (message, type = 'info', title = '') => {
      const id = Date.now() + Math.random();
      toasts.value.push({ id, message, type, title });
      setTimeout(() => {
        toasts.value = toasts.value.filter(t => t.id !== id);
      }, 3500);
    };

    const removeToast = (id) => {
      toasts.value = toasts.value.filter(t => t.id !== id);
    };

    const showPopup = (title, message, type = 'info', confirmText = 'Đã hiểu', onConfirm = null, showCancel = false) => {
      popup.value = {
        show: true,
        title,
        message,
        type,
        confirmText,
        showCancel,
        cancelText: 'Hủy',
        onConfirm
      };
    };

    const handlePopupConfirm = () => {
      if (popup.value.onConfirm && typeof popup.value.onConfirm === 'function') {
        popup.value.onConfirm();
      }
      popup.value.show = false;
    };

    // 4 Thẻ Card chuẩn giao diện ảnh mẫu
    const cards = ref([
      {
        id: 'c1',
        badge: 'Đăng trong 7 ngày',
        image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80',
        title: 'Nhân viên Kinh doanh (Sales)',
        subtitle: 'Công ty VM - TP. Tây Ninh',
        price: '12-15 Tr/Tháng',
        subprice: 'Lương: 12-15 Tr/tháng',
        category: 'tuyendung',
        btnType: 'apply',
        location: 'VM - TP. Tây Ninh'
      },
      {
        id: 'c2',
        badge: 'Cần bán',
        image: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=800&q=80',
        title: 'Căn hộ Phú Gia - Phường 3',
        subtitle: 'Căn hộ Căn hộ',
        price: '1.8 Tỷ',
        subprice: 'Diện tích: 70m²',
        category: 'batdongsan',
        btnType: 'contact',
        location: 'Phường 3, TP. Tây Ninh'
      },
      {
        id: 'c3',
        badge: 'Rao vặt',
        image: 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=800&q=80',
        title: 'Xe Honda Vision 2022 - Trảng Bàng',
        subtitle: 'Trảng Bàng, Tây Ninh',
        price: '22.5 Tr',
        subprice: 'Tình trạng: Còn mới',
        category: 'raovat',
        btnType: 'detail',
        location: 'Trảng Bàng'
      },
      {
        id: 'c4',
        badge: 'Gọi thợ gấp',
        image: 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=800&q=80',
        title: 'Sửa chữa Điện lạnh Mr. Dung',
        subtitle: 'Phục vụ tận nơi 24/7',
        price: 'Báo giá nhanh',
        subprice: 'Đánh giá: 4.8 ★',
        category: 'suachua',
        btnType: 'call',
        location: 'Hoà Thành'
      }
    ]);

    // Danh sách ghim nhanh bản đồ
    const mapQuickList = ref([
      { id: 'm1', number: 1, title: 'Nhân viên Kinh doanh (Sales)', location: 'TP. Tây Ninh' },
      { id: 'm2', number: 2, title: 'Căn hộ Phú Gia', location: 'Phường 3' },
      { id: 'm3', number: 3, title: 'Xe Honda Vision', location: 'Trảng Bàng' },
      { id: 'm4', number: 4, title: 'Điện lạnh Mr. Dung', location: 'Hoà Thành' },
      { id: 'm5', number: 5, title: 'Khách sạn Luxury', location: 'TP. Tây Ninh' }
    ]);

    const activePinItem = ref({
      title: 'Nhân viên Kinh doanh',
      price: '12-15 Tr',
      location: 'VM - TP. Tây Ninh',
      image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=120&h=120&q=80'
    });

    const selectPin = (pinNum) => {
      if (pinNum === 1) {
        activePinItem.value = { title: 'Nhân viên Kinh doanh', price: '12-15 Tr', location: 'VM - TP. Tây Ninh', image: 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=120&h=120&q=80' };
      } else if (pinNum === 2) {
        activePinItem.value = { title: 'Căn hộ Phú Gia', price: '1.8 Tỷ', location: 'Phường 3, TP. Tây Ninh', image: 'https://images.unsplash.com/photo-1545324418-cc1a3fa10c00?auto=format&fit=crop&w=120&h=120&q=80' };
      } else if (pinNum === 3) {
        activePinItem.value = { title: 'Khách sạn Luxury', price: '450k/Đêm', location: 'TP. Tây Ninh', image: 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=120&h=120&q=80' };
      } else if (pinNum === 4) {
        activePinItem.value = { title: 'Điện lạnh Mr. Dung', price: 'Báo giá nhanh', location: 'Hoà Thành', image: 'https://images.unsplash.com/photo-1621905251189-08b45d6a269e?auto=format&fit=crop&w=120&h=120&q=80' };
      } else {
        activePinItem.value = { title: 'Xe Honda Vision', price: '22.5 Tr', location: 'Trảng Bàng', image: 'https://images.unsplash.com/photo-1558981403-c5f9899a28bc?auto=format&fit=crop&w=120&h=120&q=80' };
      }
      showToast(`Đã chọn địa điểm số ${pinNum} trên bản đồ Tây Ninh`, 'info');
    };

    const selectQuickListItem = (item) => {
      selectPin(item.number);
    };

    const filteredCards = computed(() => {
      let list = [...cards.value];
      if (activeCategory.value === 'bookmark') {
        list = list.filter(c => bookmarks.value.includes(c.id));
      } else if (activeCategory.value !== 'all') {
        list = list.filter(c => c.category === activeCategory.value);
      }
      if (searchKeyword.value.trim()) {
        const kw = searchKeyword.value.toLowerCase();
        list = list.filter(c => c.title.toLowerCase().includes(kw) || c.subtitle.toLowerCase().includes(kw));
      }
      return list;
    });

    const setCategory = (cat) => {
      activeCategory.value = cat;
    };

    const filterBookmarks = () => {
      activeCategory.value = 'bookmark';
      showToast(`Đang hiển thị ${bookmarks.value.length} mục đã lưu`, 'info');
    };

    const isBookmarked = (id) => bookmarks.value.includes(id);

    const toggleBookmark = (card) => {
      const idx = bookmarks.value.indexOf(card.id);
      if (idx >= 0) {
        bookmarks.value.splice(idx, 1);
        showToast(`Đã bỏ lưu: ${card.title}`, 'info');
      } else {
        bookmarks.value.push(card.id);
        showToast(`Đã lưu bài: ${card.title}`, 'success');
      }
      localStorage.setItem('tnhub_bookmarks', JSON.stringify(bookmarks.value));
    };

    const toggleSort = () => {
      cards.value.reverse();
      showToast('Đã sắp xếp lại danh sách tin đăng', 'info');
    };

    const zoomMap = () => {
      showToast('Bản đồ Tây Ninh đã được phóng to chi tiết', 'info');
    };

    const onSearchKey = (e) => {
      if (e.key === 'Enter') {
        showToast(`Đang tìm kiếm: "${searchKeyword.value}"`, 'info');
      }
    };

    // Form handlers
    const applyForm = ref({ fullName: 'Phạm Thanh Quang', phone: '090xxxxxxx', email: 'ptquang0968@gmail.com', note: '', fileBase64: null });
    const contactForm = ref({ name: 'Phạm Thanh Quang', phone: '090xxxxxxx', message: '' });
    const postForm = ref({ title: '', category: 'tuyendung', price: '', location: '', imageBase64: null });

    const openApplyModal = (card) => {
      selectedItem.value = card;
      showApplyModal.value = true;
    };

    const openContactModal = (card) => {
      selectedItem.value = card;
      showContactModal.value = true;
    };

    const openCallModal = (card) => {
      showPopup('Gọi Điện Nhanh', `Gọi trực tiếp cho ${card.title} qua Hotline/Zalo: 0908.123.456`, 'info');
    };

    const openDetailModal = (card) => {
      showPopup(card.title, `Vị trí: ${card.subtitle}\nMức giá: ${card.price}\nLiên hệ quản trị: ptquang0968@gmail.com`, 'info');
    };

    const openPostModal = () => {
      showPostModal.value = true;
    };

    const handleCvUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (evt) => {
        applyForm.value.fileBase64 = evt.target.result;
      };
      reader.readAsDataURL(file);
    };

    const handlePostImageUpload = (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (evt) => {
        postForm.value.imageBase64 = evt.target.result;
      };
      reader.readAsDataURL(file);
    };

    const submitApplication = async () => {
      submittingApply.value = true;
      try {
        if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
          await fetch(GAS_WEB_APP_URL, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              action: 'apply_job',
              jobTitle: selectedItem.value.title,
              fullName: applyForm.value.fullName,
              phone: applyForm.value.phone,
              email: applyForm.value.email,
              note: applyForm.value.note,
              fileBase64: applyForm.value.fileBase64
            })
          });
        }
        showPopup('Ứng Tuyển Thành Công!', `Hồ sơ cho vị trí "${selectedItem.value.title}" đã được gửi tới nhà tuyển dụng.`, 'success');
        showApplyModal.value = false;
      } catch (e) {
        showToast('Lỗi khi gửi hồ sơ: ' + e.message, 'error');
      } finally {
        submittingApply.value = false;
      }
    };

    const submitContactInquiry = async () => {
      if (GAS_WEB_APP_URL && !GAS_WEB_APP_URL.includes('Dummy')) {
        fetch(GAS_WEB_APP_URL, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'contact_inquiry',
            itemTitle: selectedItem.value.title,
            customerName: contactForm.value.name,
            customerPhone: contactForm.value.phone,
            message: contactForm.value.message
          })
        });
      }
      showPopup('Đã Gửi Liên Hệ!', `Yêu cầu liên hệ về "${selectedItem.value.title}" đã được ghi nhận. Chủ tin đăng sẽ sớm gọi lại.`, 'success');
      showContactModal.value = false;
    };

    const submitNewPost = () => {
      cards.value.unshift({
        id: 'c_' + Date.now(),
        badge: 'Mới đăng',
        image: postForm.value.imageBase64 || 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?auto=format&fit=crop&w=800&q=80',
        title: postForm.value.title,
        subtitle: postForm.value.location || 'Tây Ninh',
        price: postForm.value.price || 'Thỏa thuận',
        subprice: 'Vừa xong',
        category: postForm.value.category,
        btnType: postForm.value.category === 'tuyendung' ? 'apply' : 'contact',
        location: postForm.value.location || 'Tây Ninh'
      });
      showToast('Tin đăng của bạn đã được đưa lên đầu trang!', 'success');
      showPostModal.value = false;
      postForm.value = { title: '', category: 'tuyendung', price: '', location: '', imageBase64: null };
    };

    const loginGoogle = async () => {
      try {
        if (!auth) throw new Error('Firebase Auth chưa khởi tạo');
        const provider = new GoogleAuthProvider();
        provider.setCustomParameters({ prompt: 'select_account' });
        const res = await signInWithPopup(auth, provider);
        currentUser.value = res.user;
        showToast('Chào mừng ' + (res.user.displayName || '') + '!', 'success');
      } catch (err) {
        console.warn('Login Auth info:', err.message);
        showToast('Đang ở phiên làm việc của ptquang0968@gmail.com', 'info');
      }
    };

    const saveCustomApiKey = () => {
      if (customApiKey.value.trim()) {
        localStorage.setItem('tnhub_firebase_api_key', customApiKey.value.trim());
        showToast('Đã lưu API Key! Đang tải lại...', 'success');
        setTimeout(() => window.location.reload(), 800);
      }
    };

    onMounted(() => {
      if (auth) {
        onAuthStateChanged(auth, (user) => {
          if (user) currentUser.value = user;
        });
      }
    });

    return {
      activeTab,
      activeCategory,
      viewMode,
      searchKeyword,
      userMenuOpen,
      showApplyModal,
      showContactModal,
      showPostModal,
      showConfigModal,
      submittingApply,
      selectedItem,
      customApiKey,
      currentUser,
      bookmarks,
      toasts,
      popup,
      cards,
      filteredCards,
      mapQuickList,
      activePinItem,
      applyForm,
      contactForm,
      postForm,
      showToast,
      removeToast,
      showPopup,
      handlePopupConfirm,
      setCategory,
      filterBookmarks,
      isBookmarked,
      toggleBookmark,
      toggleSort,
      zoomMap,
      onSearchKey,
      selectPin,
      selectQuickListItem,
      openApplyModal,
      openContactModal,
      openCallModal,
      openDetailModal,
      openPostModal,
      handleCvUpload,
      handlePostImageUpload,
      submitApplication,
      submitContactInquiry,
      submitNewPost,
      loginGoogle,
      saveCustomApiKey
    };
  }
}).mount('#app');
//
